import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Product Types & Catalog","description":"","frontmatter":{},"headers":[],"relativePath":"admin/products.md","filePath":"admin/products.md"}'),i={name:"admin/products.md"};function s(n,e,l,c,d,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="product-types-catalog" tabindex="-1">Product Types &amp; Catalog <a class="header-anchor" href="#product-types-catalog" aria-label="Permalink to &quot;Product Types &amp; Catalog&quot;">​</a></h1><p>FOSSBilling supports a wide range of product types, each with its own specialized automation and delivery logic.</p><hr><h2 id="📦-core-product-types" tabindex="-1">📦 Core Product Types <a class="header-anchor" href="#📦-core-product-types" aria-label="Permalink to &quot;📦 Core Product Types&quot;">​</a></h2><p>When creating a product, you must select one of the following types to enable specific automation features.</p><h3 id="_1-🖥️-hosting" tabindex="-1">1. 🖥️ Hosting <a class="header-anchor" href="#_1-🖥️-hosting" aria-label="Permalink to &quot;1. 🖥️ Hosting&quot;">​</a></h3><p>Designed for shared hosting or VPS instances.</p><ul><li><strong>Automation:</strong> Connects to cPanel, DirectAdmin, or HestiaCP.</li><li><strong>Workflow:</strong> Generates a hosting account on the remote server once the invoice is paid.</li><li><strong>Client View:</strong> Displays server IP, login credentials, and control panel links.</li></ul><h3 id="_2-🌐-domains" tabindex="-1">2. 🌐 Domains <a class="header-anchor" href="#_2-🌐-domains" aria-label="Permalink to &quot;2. 🌐 Domains&quot;">​</a></h3><p>Handles domain registration and renewals.</p><ul><li><strong>Automation:</strong> Connects to registrars like Namecheap or ResellerClub.</li><li><strong>Workflow:</strong> Performs real-time availability checks and registers the domain upon payment.</li><li><strong>Client View:</strong> Allows DNS management, WHOIS privacy toggles, and EPP code retrieval.</li></ul><h3 id="_3-💾-downloadable-products" tabindex="-1">3. 💾 Downloadable Products <a class="header-anchor" href="#_3-💾-downloadable-products" aria-label="Permalink to &quot;3. 💾 Downloadable Products&quot;">​</a></h3><p>Digital assets like software, themes, or ebooks.</p><ul><li><strong>Delivery:</strong> Generates a secure, expiring HMAC-signed download link.</li><li><strong>Security:</strong> Links are tied to the client&#39;s session and expire to prevent link sharing.</li><li><strong>Client View:</strong> A persistent &quot;Downloads&quot; tab where they can access their files.</li></ul><h3 id="_4-🔑-licenses" tabindex="-1">4. 🔑 Licenses <a class="header-anchor" href="#_4-🔑-licenses" aria-label="Permalink to &quot;4. 🔑 Licenses&quot;">​</a></h3><p>Software license keys or serial numbers.</p><ul><li><strong>Delivery:</strong> Generates a unique key based on a secure salt (e.g., <code>FOSS-XXXX-XXXX-XXXX</code>).</li><li><strong>Validation:</strong> Provides an API for your software to &quot;ping&quot; FOSSBilling for license status check.</li><li><strong>Client View:</strong> Displays the key and activation status.</li></ul><hr><h2 id="⚙️-custom-order-forms" tabindex="-1">⚙️ Custom Order Forms <a class="header-anchor" href="#⚙️-custom-order-forms" aria-label="Permalink to &quot;⚙️ Custom Order Forms&quot;">​</a></h2><p>You can attach a <strong>Custom Form</strong> to any product to gather technical details from the customer during the checkout process (e.g., Hostname, Root Password, or Server OS).</p><hr><h2 id="💰-pricing-tiers" tabindex="-1">💰 Pricing Tiers <a class="header-anchor" href="#💰-pricing-tiers" aria-label="Permalink to &quot;💰 Pricing Tiers&quot;">​</a></h2><p>FOSSBilling supports flexible billing cycles:</p><ul><li><strong>Free:</strong> No charge for the service.</li><li><strong>One-time:</strong> A single payment for lifetime access (ideal for downloads).</li><li><strong>Recurring:</strong> Monthly, Quarterly, or Annual billing with automated renewal invoices.</li></ul><hr><h2 id="📈-stock-management" tabindex="-1">📈 Stock Management <a class="header-anchor" href="#📈-stock-management" aria-label="Permalink to &quot;📈 Stock Management&quot;">​</a></h2><p>Optionally set a stock limit for physical or limited-resource products. The system will automatically mark the product as &quot;Sold Out&quot; once the limit is reached.</p>',27)])])}const g=t(i,[["render",s]]);export{p as __pageData,g as default};
